import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

let fsevents;
try {
  fsevents = require('fsevents');
} catch (cause) {
  throw new Error(
    'The "fsevents" native module is unavailable. It is a macOS-only addon ' +
      '(FSEvents API) and is installed as an optional dependency, so it will ' +
      'not be present on Linux, Windows, or in most CI containers.',
    { cause },
  );
}

export const EVENT_TYPES = Object.freeze([
  'created',
  'modified',
  'deleted',
  'moved',
  'root-changed',
  'unknown',
]);

/**
 * Start a low-level FSEvents stream.
 *
 * @param {string} path Directory (or file) to observe.
 * @param {object} [options]
 * @param {number} [options.latency] Debounce window in seconds (FSEvents latency).
 * @param {number} [options.debounce] Extra debounce window in seconds.
 * @param {string[]|RegExp|((path: string) => boolean)} [options.ignore] Path filter.
 * @param {(event: object) => void} onChange Called with each decoded native event.
 * @returns {() => void} Stops the stream.
 */
export function watchNative(path, options, onChange) {
  if (typeof options === 'function') {
    onChange = options;
    options = {};
  }
  if (typeof onChange !== 'function') {
    throw new TypeError('watchNative(path, options, onChange) requires a callback');
  }

  const stop = fsevents.watch(path, options ?? {}, (changedPath, flags, id) => {
    const info = fsevents.getInfo(changedPath, flags);
    onChange({
      path: info.path,
      event: info.event,
      changed: info.changed,
      flags: info.flags,
      id,
    });
  });

  return stop;
}

export function getInfo(path, flags) {
  return fsevents.getInfo(path, flags);
}

#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { watchNative } from './watcher.js';

const { values, positionals } = parseArgs({
  allowPositionals: true,
  options: {
    latency: { type: 'string', short: 'l' },
    ignore: { type: 'string', short: 'i' },
    debounce: { type: 'string', short: 'd' },
  },
});

const target = positionals[0] ?? process.cwd();

const options = {};
if (values.latency !== undefined) options.latency = Number(values.latency) / 1000;
if (values.debounce !== undefined) options.debounce = Number(values.debounce) / 1000;
if (values.ignore !== undefined) options.ignore = new RegExp(values.ignore);

const stop = watchNative(target, options, (event) => {
  const stamp = new Date().toISOString();
  process.stdout.write(`${stamp} ${event.event.padEnd(12)} ${event.path}\n`);
});

process.stdout.write(`Watching ${target} via FSEvents (Ctrl+C to stop)\n`);

const shutdown = () => {
  stop();
  process.exit(0);
};

process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

